/** The same for the heading's bold cells, 38 rows of 13 coverage digits. */
const TITLE_CELLS: Readonly<Record<number, string>> = {
  32: "",
  67: "",
  68: "",
  79: "",
  97: "",
  99: "",
  100: "",
  101: "",
  107: "",
  110: "",
  111: "",
  112: "",
  115: "",
  117: "",
  121: "",
}

/** The coverage values of one cell, row-major, each 0..15. */
function decode(hex: string): readonly number[] {
  const out: number[] = []
  for (let index = 0; index < hex.length; index++) {
    out.push(parseInt(hex[index]!, 16))
  }
  return out
}

/**
 * The coverage grid of a scene cell, or `undefined` when the font has none.
 */
export function cellAlpha(codePoint: number): readonly number[] | undefined {
  const hex = CELLS[codePoint]
  return hex === undefined ? undefined : decode(hex)
}

/**
 * The coverage grid of the heading cell for one character, or `undefined` when
 * the card has no bold entry for it.
 */
export function titleCellAlpha(codePoint: number): readonly number[] | undefined {
  const hex = TITLE_CELLS[codePoint]
  return hex === undefined ? undefined : decode(hex)
}
